example.code:
// .claude/settings.local.json  — created for you, yours alone, gitignored
{
  "permissions": {
    "allow": [
      "Bash(npm test:*)"
    ]
  }
}

{
  "permissions": {
    "deny":  ["Read(./.env)", "Bash(aws *)"],
    "ask":   ["Bash(git push *)"],
    "allow": ["Bash(npm test:*)", "Bash(aws s3 ls)"]
  }
}

// aws s3 ls    -> BLOCKED. deny matched first; the allow never gets a look.
// git push     -> PROMPTS. ask matched before allow could apply.
// npm test -v  -> RUNS.    no deny, no ask, allow matched.

{
  "permissions": {
    "allow": [
      "Bash(npm run test:*)",     // npm run test, npm run test:watch...
      "Bash(git diff *)",          // any git diff invocation
      "Bash(git log *)",
      "Bash(devbox run npm test)"  // NOT Bash(devbox run *)
    ],
    "deny": ["Bash(curl *)", "Bash(wget *)"]
  }
}

{
  "permissions": {
    "deny": [
      "Read(./.env)",
      "Read(./.env.*)",
      "Read(./secrets/**)",
      "Edit(./secrets/**)",
      "Read(//Users/me/.ssh/**)"
    ]
  }
}

// managed-settings.json — deployed by an administrator
{
  "permissions": {
    "disableBypassPermissionsMode": "disable",
    "disableAutoMode": "disable",
    "defaultMode": "default"
  }
}

#!/usr/bin/env bash
# .claude/hooks/block-force-push.sh
set -uo pipefail

command=$(jq -r '.tool_input.command // ""')

if printf '%s' "$command" | grep -q -- '--force'; then
  jq -n '{
    hookSpecificOutput: {
      hookEventName: "PreToolUse",
      permissionDecision: "deny",
      permissionDecisionReason: "Force push blocked. Use --force-with-lease."
    }
  }'
fi
exit 0   # no output = no decision; the normal permission flow applies

{
  "permissions": { "allow": ["Bash"] },

  "hooks": {
    "PreToolUse": [{
      "matcher": "Bash",
      "hooks": [{
        "type": "command",
        "command": "${CLAUDE_PROJECT_DIR}/.claude/hooks/gate.sh",
        "args": []
      }]
    }]
  }
}

// gate.sh inspects the whole command and exits 2 for the cases you
// refuse — something a prefix glob could never express safely.

// .mcp.json — committed, shared with the team
{
  "mcpServers": {
    "github": { "type": "http", "url": "https://api.githubcopilot.com/mcp/" }
  }
}

// .claude/settings.json — approve only the read-only tools
{
  "permissions": {
    "allow": ["mcp__github__get_*", "mcp__github__list_*"]
  }
}

{
  "scripts": {
    "lint:claude": "git diff main | claude -p --bare \"you are a typo linter. for each typo in this diff, report filename:line on one line and the issue on the next. return nothing else.\""
  }
}

messages = [{"role": "user", "content": user_input}]

while True:
    response = client.messages.create(
        model="claude-opus-5", max_tokens=16000,
        tools=tools, messages=messages,
    )
    if response.stop_reason == "end_turn":
        break

    messages.append({"role": "assistant", "content": response.content})

    results = [
        {"type": "tool_result", "tool_use_id": b.id, "content": run(b.name, b.input)}
        for b in response.content if b.type == "tool_use"
    ]
    messages.append({"role": "user", "content": results})   # ALL of them, ONE message

{
  "sandbox": {
    "enabled": true,
    "filesystem": {
      "denyRead":  ["~/"],
      "allowRead": ["~/code", "~/.cache"]
    },
    "credentials": {
      "files": [{ "path": "~/.ssh", "mode": "deny" }],
      "env":   [{ "name": "GITHUB_TOKEN", "mode": "deny" }]
    },
    "network": { "allowedDomains": ["registry.npmjs.org"] }
  }
}
